```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const app = express();
const SECRET = process.env.JWT_SECRET || 'dev-secret';

// In-memory store (replace with DB in production)
const users = {}; // { email: { hash } }
const failedAttempts = {}; // { email: { count, resetTime } }

const RATE_LIMIT = { maxAttempts: 5, windowMs: 15 * 60 * 1000 };

app.use(express.json());

function isRateLimited(email) {
  const record = failedAttempts[email];
  if (!record) return false;
  if (Date.now() > record.resetTime) {
    delete failedAttempts[email];
    return false;
  }
  return record.count >= RATE_LIMIT.maxAttempts;
}

function recordFailure(email) {
  const now = Date.now();
  failedAttempts[email] = failedAttempts[email] || { count: 0, resetTime: now + RATE_LIMIT.windowMs };
  failedAttempts[email].count++;
}

function clearFailures(email) {
  delete failedAttempts[email];
}

app.post('/signup', async (req, res) => {
  const { email, password } = req.body;
  if (!email?.trim() || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }
  if (users[email]) {
    return res.status(409).json({ error: 'Email already exists' });
  }
  try {
    const hash = await bcrypt.hash(password, 10);
    users[email] = { hash, createdAt: Date.now() };
    res.status(201).json({ message: 'Signup successful' });
  } catch (err) {
    res.status(500).json({ error: 'Signup failed' });
  }
});

app.post('/login', async (req, res) => {
  const { email, password } = req.body;
  if (!email?.trim() || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }
  if (isRateLimited(email)) {
    return res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
  }

  const user = users[email];
  if (!user) {
    recordFailure(email);
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  try {
    const isValid = await bcrypt.compare(password, user.hash);
    if (!isValid) {
      recordFailure(email);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    clearFailures(email);
    const token = jwt.sign({ email }, SECRET, { expiresIn: '7d' });
    res.json({ token });
  } catch (err) {
    res.status(500).json({ error: 'Login failed' });
  }
});

function auth(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token required' });
  jwt.verify(token, SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
}

app.get('/me', auth, (req, res) => {
  res.json({ email: req.user.email });
});

app.listen(3000);
```

**Setup:** `npm install express bcrypt jsonwebtoken`

**Key points:**
- **Hashing:** bcrypt with salt rounds=10; irreversible, no plaintext stored.
- **Sessions:** JWT stateless tokens, 7-day expiry. Decode with middleware `auth()`.
- **Rate limit:** Per-email tracker resets after 15 min; 5 max attempts; generic "Invalid email or password" error (no user enumeration).
- **Signup:** Prevents duplicate emails.
- **Login:** Clears failure counter on success; increments on mismatch or unknown email.

Replace in-memory `users` and `failedAttempts` with a database (PostgreSQL + bcrypt, Redis for rate limit window). Set `JWT_SECRET` env var in production.
